class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        self.best = n * m
        grid = [[False] * m for _ in range(n)]

        def dfs(cnt):
            if cnt >= self.best:
                return
            pos = None
            for i in range(n):
                for j in range(m):
                    if not grid[i][j]:
                        pos = (i, j)
                        break
                if pos:
                    break
            if not pos:
                self.best = cnt
                return
            i, j = pos
            s = 1
            while i + s < n and j + s < m:
                ok = True
                for x in range(i, i + s + 1):
                    for y in range(j, j + s + 1):
                        if grid[x][y]:
                            ok = False
                            break
                    if not ok:
                        break
                if not ok:
                    break
                s += 1
            for sz in range(s, 0, -1):
                for x in range(i, i + sz):
                    for y in range(j, j + sz):
                        grid[x][y] = True
                dfs(cnt + 1)
                for x in range(i, i + sz):
                    for y in range(j, j + sz):
                        grid[x][y] = False

        dfs(0)
        return self.best

