class Solution {
    int n, m, best;
    vector<vector<bool>> grid;
public:
    int tilingRectangle(int nn, int mm) {
        n = nn; m = mm; best = n * m;
        grid.assign(n, vector<bool>(m, false));
        dfs(0);
        return best;
    }
    void dfs(int cnt) {
        if (cnt >= best) return;
        int pi = -1, pj = -1;
        for (int i = 0; i < n && pi < 0; i++)
            for (int j = 0; j < m; j++)
                if (!grid[i][j]) { pi = i; pj = j; break; }
        if (pi < 0) { best = cnt; return; }
        int s = 1;
        while (pi + s < n && pj + s < m) {
            bool ok = true;
            for (int x = pi; x <= pi + s && ok; x++)
                for (int y = pj; y <= pj + s; y++)
                    if (grid[x][y]) { ok = false; break; }
            if (!ok) break;
            s++;
        }
        for (int sz = s; sz >= 1; sz--) {
            for (int x = pi; x < pi + sz; x++)
                for (int y = pj; y < pj + sz; y++) grid[x][y] = true;
            dfs(cnt + 1);
            for (int x = pi; x < pi + sz; x++)
                for (int y = pj; y < pj + sz; y++) grid[x][y] = false;
        }
    }
};

