class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        self.best = n * m
        h = [0] * m

        def dfs(cnt):
            if cnt >= self.best:
                return
            j = min(range(m), key=lambda x: h[x])
            base = h[j]
            if base == n:
                self.best = cnt
                return
            s = 1
            while j + s < m and h[j + s] == base and base + s + 1 <= n:
                s += 1
            for sz in range(s, 0, -1):
                for k in range(j, j + sz):
                    h[k] += sz
                dfs(cnt + 1)
                for k in range(j, j + sz):
                    h[k] -= sz

        dfs(0)
        return self.best

